const D = { energy:.62, density:.5, alpha:.78, warp:.42, weight:.4, speed:1, scale:1, hue:38, x:.5, y:.5, style:'ink', act:'breathe', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,v)=>{h=((h%360)+360)%360;s/=100;v/=100;const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,b;const sg=Math.floor(h/60)%6;if(sg===0){r=c;g=x;b=0;}else if(sg===1){r=x;g=c;b=0;}else if(sg===2){r=0;g=c;b=x;}else if(sg===3){r=0;g=x;b=c;}else if(sg===4){r=x;g=0;b=c;}else{r=c;g=0;b=x;}return [((r+m)*255)|0,((g+m)*255)|0,((b+m)*255)|0];};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,t=K.t,key=W+'x'+H;

// ---- size-keyed buffers: a coarse capture of the live frame + the ink plate
if(!S.g||S.key!==key){
  let gw,gh;
  if(W>=H){ gw=220; gh=Math.max(20,Math.round(220*H/W)); } else { gh=220; gw=Math.max(20,Math.round(220*W/H)); }
  if(S.g&&S.g.remove)S.g.remove();
  if(S.ink&&S.ink.remove)S.ink.remove();
  S.gw=gw; S.gh=gh;
  S.g=createGraphics(gw,gh); S.g.pixelDensity(1);
  S.ink=createGraphics(gw,gh); S.ink.pixelDensity(1);
  S.vf=new Float32Array(gw*gh);
  S.lx=[]; for(let k=0;k<6;k++) S.lx.push(new Float32Array(gw));
  S.ly=[]; for(let k=0;k<6;k++) S.ly.push(new Float32Array(gh));
  S.key=key;
}
const gw=S.gw,gh=S.gh,g=S.g,ink=S.ink,vf=S.vf,LX=S.lx,LY=S.ly;

// ---- sample the composited frame underneath us
g.clear();
g.drawingContext.drawImage(drawingContext.canvas,0,0,gw,gh);
g.loadPixels();
const px=g.pixels;

const en=clp(P.energy,0,1);
const sp=0.45+clp(P.speed,.15,4)*0.55;
const sc=1.6/Math.max(0.25,P.scale);
const warp=clp(P.warp,0,1), wEff=0.06+warp*0.62;
const lv=6+Math.round(clp(P.density,0,1)*18);
const hue=((P.hue%360)+360)%360;
const style=P.style;
const isHatch=style==='hatch', isAdd=(style==='neon'||style==='xray');
const mode = style==='neon'?1 : style==='xray'?2 : 0;

// ---- act: multi-minute programs
let lvOff=t*0.02*sp, wMul=1, reveal=0;
if(P.act==='tide'){ lvOff = t*0.11*sp + Math.sin(t*0.071)*0.9; }
else if(P.act==='pulse'){ wMul = 1 + (K.pulse*0.5 + A.bass*0.5)*0.6*en; lvOff = t*0.03*sp + K.swell*0.35; }
else if(P.act==='survey'){ reveal=1; }
const bandY = 0.5 + 0.40*Math.sin(t*0.13*sp) + 0.12*Math.sin(t*0.37*sp+1.1);

// ---- separable spatial LUTs (keeps the trig at O(gw+gh), not O(gw*gh))
const ox=(P.x-0.5)*4.0+fr(3)*7.0, oy=(P.y-0.5)*4.0+fr(7)*7.0, ar=gw/gh;
for(let i=0;i<gw;i++){
  const nx=((i+0.5)/gw-0.5)*2*ar*sc+ox;
  LX[0][i]=Math.sin(nx*2.10); LX[1][i]=Math.cos(nx*2.10);
  LX[2][i]=Math.sin(nx*1.31); LX[3][i]=Math.cos(nx*1.31);
  LX[4][i]=Math.sin(nx*2.70); LX[5][i]=Math.cos(nx*2.70);
}
for(let j=0;j<gh;j++){
  const ny=((j+0.5)/gh-0.5)*2*sc+oy;
  LY[0][j]=Math.sin(ny*1.70); LY[1][j]=Math.cos(ny*1.70);
  LY[2][j]=Math.sin(ny*1.31); LY[3][j]=Math.cos(ny*1.31);
  LY[4][j]=Math.sin(ny*2.70); LY[5][j]=Math.cos(ny*2.70);
