// four incommensurate real-time phases -> the line never re-phases at 8s
const p1=t*0.31*sp, p2=-t*0.23*sp+1.3, p3=t*0.41*sp, p4=-t*0.17*sp+2.1;
const S1=Math.sin(p1),C1=Math.cos(p1),S2=Math.sin(p2),C2=Math.cos(p2);
const S3=Math.sin(p3),C3=Math.cos(p3),S4=Math.sin(p4),C4=Math.cos(p4);

// ---- pass 1: the scalar field = frame luminance + a living warp
for(let j=0;j<gh;j++){
  const s2=LY[0][j],c2=LY[1][j],s3b=LY[2][j],c3b=LY[3][j],s4b=LY[4][j],c4b=LY[5][j];
  const row=j*gw;
  for(let i=0;i<gw;i++){
    const o=(row+i)*4;
    const lum=(px[o]*0.299+px[o+1]*0.587+px[o+2]*0.114)*0.00392157;
    const s1=LX[0][i],c1=LX[1][i],s3=LX[2][i],c3=LX[3][i],s4=LX[4][i],c4=LX[5][i];
    const sxy3=s3*c3b+c3*s3b, cxy3=c3*c3b-s3*s3b;
    const sxy4=s4*c4b-c4*s4b, cxy4=c4*c4b+s4*s4b;
    const n = 0.5*(s1*C1+c1*S1) + 0.4*(s2*C2+c2*S2) + 0.35*(sxy3*C3+cxy3*S3) + 0.3*(sxy4*C4+cxy4*S4);
    vf[row+i] = (lum + wEff*n*0.645)*lv + lvOff;
  }
}

// ---- pass 2: gradient-normalised level crossings -> even-weight relief contours
ink.loadPixels();
const ip=ink.pixels;
const lw=Math.max(0.2,(0.35+clp(P.weight,0,1)*1.7)*wMul);
const inkA=clp(clp(P.alpha,0,1)*(0.45+0.75*en),0,1);
const lipA=0.22+0.62*en;
const dk=hsb2rgb(hue,28,5), lp=hsb2rgb(hue,17,96);
const gl0=hsb2rgb(hue,72,100), gl1=hsb2rgb((hue+42)%360,58,100);
const xr0=hsb2rgb((hue+150)%360,30,100), xr1=hsb2rgb((hue+170)%360,12,100);
const hAng=t*0.041*sp+fr(11)*6.28, hc=Math.cos(hAng)*0.62, hs=Math.sin(hAng)*0.62;
const halo=lw*4;
for(let j=0;j<gh;j++){
  const row=j*gw, jm=(j>0?j-1:j)*gw, jp=(j<gh-1?j+1:j)*gw;
  let rev=1;
  if(reveal){ rev=clp(1.18-Math.abs(j/gh-bandY)*3.2,0.10,1); }
  for(let i=0;i<gw;i++){
    const idx=row+i, o=idx*4;
    const v=vf[idx];
    const vx=vf[row+(i<gw-1?i+1:i)]-vf[row+(i>0?i-1:i)];
    const vy=vf[jp+i]-vf[jm+i];
    const grad=Math.max(0.004,Math.sqrt(vx*vx+vy*vy)*0.5);
    const f=v-Math.round(v);
    const d=f/grad;
    const ad=Math.abs(d);
    let a=ad<lw?(1-ad/lw):0;
    a=a*a*(3-2*a);
    if(mode===1&&ad<halo) a=Math.max(a,(1-ad/halo)*0.3);
    if(isHatch) a*=0.30+0.70*(0.5+0.5*Math.sin(i*hc+j*hs));
    a*=rev;
    if(a<=0.004){ ip[o]=0;ip[o+1]=0;ip[o+2]=0;ip[o+3]=0; continue; }
    if(mode===0){
      if(d<0){ ip[o]=dk[0];ip[o+1]=dk[1];ip[o+2]=dk[2]; ip[o+3]=(a*inkA*255)|0; }
      else   { ip[o]=lp[0];ip[o+1]=lp[1];ip[o+2]=lp[2]; ip[o+3]=(a*inkA*lipA*255)|0; }
    } else if(mode===1){
      const c=d<0?gl0:gl1; ip[o]=c[0];ip[o+1]=c[1];ip[o+2]=c[2]; ip[o+3]=(a*inkA*255)|0;
    } else {
      const c=d<0?xr0:xr1; ip[o]=c[0];ip[o+1]=c[1];ip[o+2]=c[2]; ip[o+3]=(a*inkA*0.9*255)|0;
    }
  }
}
ink.updatePixels();

noStroke();
if(mode===2){ blendMode(BLEND); fill(hue,24,6,32+22*en); rect(0,0,W,H); }
blendMode(isAdd?ADD:BLEND);
image(ink,0,0,W,H);
